with j as (select * from jsonb_to_recordset($law7d0028$[{"code_id":"BK_RF","article_number":"50","version_date":"1998-07-31","article_text":"В федеральный бюджет зачисляются налоговые доходы от следующих федеральных налогов и сборов,  налогов,  предусмотренных специальными налоговыми режимами:\n\nналога на прибыль организаций по ставке,  установленной для зачисления указанного налога в федеральный бюджет,  - по нормативу 100 процентов;\n\nналога на прибыль организаций (в части доходов иностранных организаций,  не связанных с деятельностью в Российской Федерации через постоянное представительство,  а также в части доходов,  полученных в виде дивидендов и процентов по государственным и муниципальным ценным бумагам)  - по нормативу 100 процентов;\n\nналога на прибыль организаций при выполнении соглашений о разделе продукции,  заключенных до вступления в силу Федерального закона от 30 декабря 1995 года № 225-ФЗ \"О соглашениях о разделе продукции\" (далее - Федеральный закон \"О соглашениях о разделе продукции\")  и не предусматривающих специальных налоговых ставок для зачисления указанного налога в федеральный бюджет и бюджеты субъектов Российской Федерации,  - по нормативу 25 процентов; (В редакции Федерального закона от 30.11.2016 № 409-ФЗ)\n\nналога на добавленную стоимость - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 15.04.2019 № 62-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 15.04.2019 № 62-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 15.04.2019 № 62-ФЗ)\n\nакцизов на алкогольную продукцию с объемной долей этилового спирта свыше 9 процентов,  за исключением пива,  вин (кроме крепленого (ликерного)  вина) ,  вин наливом,  плодовой алкогольной продукции,  игристых вин,  включая российское шампанское,  а также за исключением виноградосодержащих напитков,  плодовых алкогольных напитков,  изготавливаемых без добавления ректификованного этилового спирта,  произведенного из пищевого сырья,  и (или)  без добавления спиртованных виноградного или иного плодового сусла,  и (или)  без добавления дистиллятов,  и (или)  без добавления крепленого (ликерного)  вина,  - по нормативу 16 процентов; (Дополнение абзацем - Федеральный закон от 03.12.2012 № 244-ФЗ)  (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\nакцизов на табачную продукцию - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 04.10.2014 № 283-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 30.12.2008 № 310-ФЗ)\n\nакцизов на автомобили легковые и мотоциклы - по нормативу 100 процентов;\n\nабзац; (Дополнение абзацем - Федеральный закон от 23.05.2016 № 145-ФЗ)  (Утратил силу - Федеральный закон от 28.11.2018 № 456-ФЗ)\n\nакцизов на средние дистилляты,  производимые на территории Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.12.2017 № 434-ФЗ)  (В редакции Федерального закона от 29.11.2021 № 384-ФЗ)\n\nакцизов по подакцизным товарам и продукции,  ввозимым на территорию Российской Федерации,  - по нормативу 100 процентов;\n\nналога на добычу полезных ископаемых в виде углеводородного сырья (газ горючий природный)  - по нормативу 100 процентов;\n\nналога на добычу полезных ископаемых в виде углеводородного сырья (за исключением газа горючего природного)  - по нормативу 100 процентов; (В редакции Федерального закона от 22.09.2009 № 218-ФЗ)\n\nналога на добычу полезных ископаемых (за исключением полезных ископаемых,  в отношении которых при налогообложении установлен рентный коэффициент,  отличный от 1,  полезных ископаемых в виде углеводородного сырья,  природных алмазов и общераспространенных полезных ископаемых,  угля коксующегося,  железных руд,  апатит-магнетитовых,  апатит-штаффелитовых и маложелезистых апатитовых руд,  многокомпонентной комплексной руды,  в отношении которой при налогообложении установлен коэффициент,  характеризующий стоимость ценных компонентов в руде)  - по нормативу 40 процентов; (В редакции федеральных законов от 19.12.2006 № 237-ФЗ,  от 15.10.2020 № 327-ФЗ,  от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых на континентальном шельфе Российской Федерации,  в исключительной экономической зоне Российской Федерации,  за пределами территории Российской Федерации - по нормативу 100 процентов;\n\nрегулярных платежей за добычу полезных ископаемых (роялти)  при выполнении соглашений о разделе продукции в виде углеводородного сырья (газ горючий природный)  - по нормативу 100 процентов;\n\nрегулярных платежей за добычу полезных ископаемых (роялти)  при выполнении соглашений о разделе продукции в виде углеводородного сырья (за исключением газа горючего природного)  - по нормативу 95 процентов;\n\nрегулярных платежей за добычу полезных ископаемых (роялти)  на континентальном шельфе,  в исключительной экономической зоне Российской Федерации,  за пределами территории Российской Федерации при выполнении соглашений о разделе продукции - по нормативу 100 процентов;\n\nсбора за пользование объектами водных биологических ресурсов (исключая внутренние водные объекты)  - по нормативу 20 процентов; (В редакции Федерального закона от 06.12.2007 № 333-ФЗ)\n\nсбора за пользование объектами водных биологических ресурсов (по внутренним водным объектам)  - по нормативу 20 процентов; (В редакции Федерального закона от 06.12.2007 № 333-ФЗ)\n\nводного налога - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nгосударственной пошлины (за исключением государственной пошлины за совершение юридически значимых действий,  указанных в статьях 56,  61,  611,  612,  613,  614,  615 и 616 настоящего Кодекса,  государственной пошлины,  предусмотренной абзацами тридцатым и тридцать первым настоящей статьи)  - по нормативу 100 процентов; (В редакции федеральных законов от 27.12.2009 № 374-ФЗ,  от 21.07.2014 № 249-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 07.03.2018 № 45-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 03.12.2012 № 244-ФЗ)  (Утратил силу - Федеральный закон от 24.11.2014 № 374-ФЗ)\n\nгосударственной пошлины за совершение федеральными органами исполнительной власти юридически значимых действий в случае подачи заявления и (или)  документов,  необходимых для их совершения,  в многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 50 процентов; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 249-ФЗ)\n\nгосударственной пошлины за совершение федеральными органами исполнительной власти юридически значимых действий в случае подачи заявления и (или)  документов,  необходимых для их совершения,  в электронной форме и выдачи документов через многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 75 процентов; (Дополнение абзацем - Федеральный закон от 07.03.2018 № 45-ФЗ)\n\nакцизов на нефтяное сырье,  направленное на переработку,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.11.2018 № 456-ФЗ)\n\nакцизов на темное судовое топливо,  производимое на территории Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.11.2018 № 456-ФЗ)\n\nналога на дополнительный доход от добычи углеводородного сырья - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.11.2018 № 456-ФЗ)\n\nналога на доходы физических лиц в отношении доходов в виде процентов,  полученных по вкладам (остаткам на счетах)  в банках,  находящихся на территории Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)\n\nналога на доходы физических лиц в отношении доходов в виде процента (купона,  дисконта) ,  полученных по обращающимся облигациям российских организаций,  номинированным в рублях и эмитированным после 1 января 2017 года,  а также доходов в виде суммы процентов по государственным казначейским обязательствам,  облигациям и другим государственным ценным бумагам бывшего СССР,  государств - участников Союзного государства - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)  (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на добычу полезных ископаемых,  в отношении которых при налогообложении установлен рентный коэффициент,  отличный от 1,  - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей,  уплачиваемой на основании налогового уведомления налогоплательщиками,  для которых выполнено условие,  предусмотренное абзацем восьмым пункта 6 статьи 228 Налогового кодекса Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nналога на добычу полезных ископаемых в виде угля коксующегося - по нормативу 70 процентов; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде железной руды (за исключением окисленных железистых кварцитов)  - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде апатит-магнетитовых,  апатит-штаффелитовых и маложелезистых апатитовых руд - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде многокомпонентной комплексной руды,  в отношении которой при налогообложении установлен коэффициент,  характеризующий стоимость ценных компонентов в руде,  - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nакциза на сталь жидкую - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога,  взимаемого в связи с применением специального налогового режима \"Автоматизированная упрощенная система налогообложения\",  в том числе минимального налога,  - по нормативу 46 процентов; (Дополнение абзацем - Федеральный закон от 25.02.2022 № 22-ФЗ)\n\nналога на сверхприбыль (обеспечительного платежа по налогу)  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей и составляющей не более 5 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать девятом и пятьдесят первом настоящей статьи) ,  - по нормативу 13 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 702 тысячи рублей,  относящейся к части налоговой базы,  превышающей 5 миллионов рублей и составляющей не более 20 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать девятом и пятьдесят первом настоящей статьи) ,  - по нормативу 28 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 3402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 20 миллионов рублей и составляющей не более 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать девятом и пятьдесят первом настоящей статьи) ,  - по нормативу 35 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 9402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать девятом и пятьдесят первом настоящей статьи) ,  - по нормативу 40 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 6 статьи 210 Налогового кодекса Российской Федерации,  превышающей 2, 4 миллиона рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом и тридцать шестом настоящей статьи) ,  а также налога на доходы физических лиц в отношении доходов физических лиц,  не являющихся налоговыми резидентами Российской Федерации,  указанных в абзаце девятом пункта 3 статьи 224 Налогового кодекса Российской Федерации,  в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей,  - по нормативу 13 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  а также налога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  - по нормативу 13 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на природный газ,  полученный для производства аммиака,  - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на фармацевтическую субстанцию спирта этилового - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на никотиновое сырье - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на бестабачную никотинсодержащую смесь для нагревания - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  уплачиваемого при выполнении условий,  предусмотренных статьями 2131,  217,  2191 и 2192 Налогового кодекса Российской Федерации,  в случаях,  если сумма всех налоговых баз налогоплательщика превышает 50 миллионов рублей,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n(Статья в редакции Федерального\n\nгражданина,  индивидуального предпринимателя в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве) \" - в части задолженности по платежам в бюджет,  от исполнения обязанности по уплате которой он освобожден в соответствии с указанным Федеральным законом; (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n21)  (Дополнение подпунктом - Федеральный закон от 07.04.2020 № 114-ФЗ)  (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n3)  ликвидации организации - плательщика платежей в бюджет в части задолженности по платежам в бюджет,  не погашенной по причине недостаточности имущества организации и (или)  невозможности ее погашения учредителями (участниками)  указанной организации в пределах и порядке,  которые установлены законодательством Российской Федерации; (В редакции Федерального закона от 07.04.2020 № 114-ФЗ)\n\n4)  применения актов об амнистии или помилования в отношении осужденных к наказанию в виде штрафа или принятия судом решения,  в соответствии с которым администратор доходов бюджета утрачивает возможность взыскания задолженности по платежам в бюджет,  в том числе в связи с истечением установленного срока ее взыскания; (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n5)  вынесения судебным приставом-исполнителем постановления об окончании исполнительного производства при возврате взыскателю исполнительного документа по основанию,  предусмотренному пунктом 3 или 4 части 1 статьи 46 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\",  если с даты образования задолженности,  размер которой не превышает размера требований к должнику,  установленного законодательством Российской Федерации о несостоятельности (банкротстве)  для возбуждения производства по делу о банкротстве,  прошло более пяти лет; (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n51)  принятия судом акта о возвращении заявления о признании должника банкротом или прекращении производства по делу о банкротстве в связи с отсутствием средств,  достаточных для возмещения судебных расходов на проведение процедур,  применяемых в деле о банкротстве; (Дополнение подпунктом - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n6)  исключения юридического лица по решению регистрирующего органа из единого государственного реестра юридических лиц и наличия ранее вынесенного судебным приставом-исполнителем постановления об окончании исполнительного производства в связи с возвращением взыскателю исполнительного документа по основанию,  предусмотренному пунктом 3 или 4 части 1 статьи 46 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\",  - в части задолженности по платежам в бюджет,  не погашенной по причине недостаточности имущества организации и невозможности ее погашения учредителями (участниками)  указанной организации в случаях,  предусмотренных законодательством Российской Федерации. В случае признания решения регистрирующего органа об исключении юридического лица из единого государственного реестра юридических лиц в соответствии с Федеральным законом от 8 августа 2001 года № 129-ФЗ \"О государственной регистрации юридических лиц и индивидуальных предпринимателей\" недействительным задолженность по платежам в бюджет,  ранее признанная безнадежной к взысканию в соответствии с настоящим подпунктом,  подлежит восстановлению в бюджетном (бухгалтерском)  учете. (Дополнение подпунктом - Федеральный закон от 07.04.2020 № 114-ФЗ)\n\n2. Наряду со случаями,  предусмотренными пунктом 1 настоящей статьи,  неуплаченные административные штрафы признаются безнадежными к взысканию,  если судьей,  органом,  должностным лицом,  вынесшими постановление о назначении административного наказания,  в случаях,  предусмотренных Кодексом Российской Федерации об административных правонарушениях,  вынесено постановление о прекращении исполнения постановления о назначении административного наказания. (В редакции Федерального закона от 07.04.2020 № 114-ФЗ)\n\n3. Решение о признании безнадежной к взысканию задолженности по платежам в бюджет принимается администратором доходов бюджета на основании документов,  подтверждающих обстоятельства,  предусмотренные пунктами 1 и 2 настоящей статьи.\n\n4. Порядок принятия решений о признании безнадежной к взысканию задолженности по платежам в бюджет определяется главным администратором доходов бюджета в соответствии с общими требованиями,  установленными Правительством Российской Федерации.\n\n5. Списание (восстановление)  в бюджетном (бухгалтерском)  учете задолженности по платежам в бюджет осуществляется администратором доходов бюджета на основании решения о признании безнадежной к взысканию задолженности по платежам в бюджет.\n\nПорядок отражения операций по списанию (восстановлению)  в бюджетном (бухгалтерском)  учете задолженности по платежам в бюджет устанавливается Министерством финансов Российской Федерации.\n\n6. Положения настоящей статьи не распространяются на платежи,  установленные законодательством о налогах и сборах,  законодательством Российской Федерации об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний,  правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании,  на денежные обязательства перед публично-правовым образованием. (В редакции федеральных законов от 03.07.2016 № 346-ФЗ,  от 28.12.2017 № 434-ФЗ,  от 02.08.2019 № 278-ФЗ,  от 07.04.2020 № 114-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 29.12.2015 № 406-ФЗ)","article_title":"Статья 50. Налоговые доходы федерального бюджета","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9900a66faba361e2bf3cb831dbcf0b3e12aca264243054b92ba6e9d466b5e45"}]$law7d0028$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
